<?php declare(strict_types=1);require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../includes/functions.php';$id=0;$editing=false;$m=['member_number'=>'','full_name'=>'','email'=>'','phone'=>'','status'=>'active','date_joined'=>date('Y-m-d')];if($editing){$s=$pdo->prepare('SELECT * FROM members WHERE member_id=?');$s->execute([$id]);$m=$s->fetch();if(!$m){set_flash('error','Member not found.');redirect('/members/index.php');}}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null))$error='Session expired. Refresh and try again.';else{$no=trim($_POST['member_number']??'');$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$status=$_POST['status']??'active';$joined=$_POST['date_joined']??'';if($no===''||$name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($phone)>30||!in_array($status,['active','suspended'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$joined))$error='Enter a valid member number, name, email, status and joining date.';else{try{if($editing){$s=$pdo->prepare('UPDATE members SET member_number=?,full_name=?,email=?,phone=?,status=?,date_joined=? WHERE member_id=?');$s->execute([$no,$name,$email,$phone?:null,$status,$joined,$id]);}else{$s=$pdo->prepare('INSERT INTO members(member_number,full_name,email,phone,status,date_joined) VALUES(?,?,?,?,?,?)');$s->execute([$no,$name,$email,$phone?:null,$status,$joined]);}set_flash('success',$editing?'Member updated.':'Member added.');redirect('/members/index.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'Member number or email is already registered.':'Unable to save member details.';}}}}$pageTitle=$editing?'Edit member':'Add member';$activePage='members';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
<main class="main-content"><header class="topbar"><div><span class="eyebrow">MEMBERS REGISTER</span><h1><?=e($pageTitle)?></h1></div></header><section class="content-card"><div class="section-heading"><h2><?=e($pageTitle)?></h2><a class="btn btn-secondary" href="index.php">Back to members</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Member number *</label><input name="member_number" required maxlength="30" value="<?=e($_POST['member_number']??$m['member_number'])?>"></div><div class="field"><label>Full name *</label><input name="full_name" required maxlength="150" value="<?=e($_POST['full_name']??$m['full_name'])?>"></div><div class="field"><label>Email *</label><input type="email" name="email" required maxlength="150" value="<?=e($_POST['email']??$m['email'])?>"></div><div class="field"><label>Telephone</label><input name="phone" maxlength="30" value="<?=e($_POST['phone']??$m['phone'])?>"></div><div class="field"><label>Status</label><select name="status"><option value="active" <?=($_POST['status']??$m['status'])==='active'?'selected':''?>>Active</option><option value="suspended" <?=($_POST['status']??$m['status'])==='suspended'?'selected':''?>>Suspended</option></select></div><div class="field"><label>Date joined *</label><input type="date" name="date_joined" required value="<?=e($_POST['date_joined']??$m['date_joined'])?>"></div></div><div class="form-actions"><button class="btn">Save member</button><a class="btn btn-secondary" href="index.php">Cancel</a></div></form></section></main><?php require __DIR__.'/../includes/footer.php';?>